// Unpin vs !Unpin: what Pin actually restricts.
//
// Most types are `Unpin` (moving them is always safe), and for those Pin is a
// no-op wrapper: you can create it freely and get `&mut T` back out.
// Pin only restricts types that are `!Unpin` (e.g. ones with `PhantomPinned`,
// or futures generated by `async`).

use std::marker::PhantomPinned;
use std::pin::{pin, Pin};

struct Movable {
    n: u32,
}

struct Immovable {
    n: u32,
    _pin: PhantomPinned,
}

fn main() {
    // --- Unpin type ---
    let mut a = Movable { n: 1 };
    let mut b = Movable { n: 2 };

    // Pin::new is safe only for Unpin types.
    let mut pa: Pin<&mut Movable> = Pin::new(&mut a);
    // get_mut is also only available for Unpin types.
    pa.as_mut().get_mut().n += 10;
    // So even a pinned Unpin value can be moved (swapped here).
    std::mem::swap(pa.get_mut(), &mut b);
    println!("Unpin:  a.n = {}, b.n = {}", a.n, b.n);

    // --- !Unpin type ---
    let c = Immovable {
        n: 3,
        _pin: PhantomPinned,
    };

    // Pin::new(&mut c) does not compile:
    //     error[E0277]: `PhantomPinned` cannot be unpinned
    // Use pin! (on the stack) or Box::pin (on the heap) instead.
    // After pin!, `c` itself is moved into the macro and cannot be touched again.
    let pc: Pin<&mut Immovable> = pin!(c);

    // Reading through Pin is always fine (Pin<P> implements Deref).
    println!("!Unpin: c.n = {}", pc.n);

    // But `pc.get_mut()` does not compile, so safe code cannot move it out.
    // The only way is `unsafe { pc.get_unchecked_mut() }`, where you promise not to move it.
    let r: &mut Immovable = unsafe { pc.get_unchecked_mut() };
    r.n += 10; // modifying a field in place is fine; moving the whole value is not
    println!("!Unpin: c.n = {} (modified in place via unsafe)", r.n);
}
